description:
{# The company and the period come from the report's filters (doc = the filter values). #}
<b>{{ doc.company or "" }}</b>
{% if doc.from_date and doc.to_date %}<br>{{ _("For the period from {0} to {1}")|replace("{0}", frappe.utils.formatdate(doc.from_date))|replace("{1}", frappe.utils.formatdate(doc.to_date)) }}{% elif doc.to_date %}<br>{{ _("As on {0}")|replace("{0}", frappe.utils.formatdate(doc.to_date)) }}{% endif %}

{# HTML is allowed: a framed word, then who printed it and when. #}
<div style="display:inline-block;border:1.5px solid currentColor;border-radius:1.5mm;padding:.6mm 4mm;font-weight:700;letter-spacing:.18em">{{ _("CONFIDENTIAL") }}</div>
<div style="margin-top:1mm">{{ _("For internal use only. Printed by {0} on {1}")|replace("{0}", printed_by)|replace("{1}", frappe.utils.format_datetime(printed_on)) }}</div>

{# Plain text without tags: each line prints on its own line. #}
{{ title }} · {{ _("Draft copy") }}
{{ _("Figures may change before approval.") }}

{# Choose «Instead of the report title» to make this heading the title of the pages. #}
{{ _("Submitted to the Board of Directors") }}
{{ doc.company or "" }}{% if doc.fiscal_year %} · {{ _("Fiscal Year {0}")|replace("{0}", doc.fiscal_year) }}{% endif %}
